import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# Custom CUDA kernel for mean reduction along the last dimension.
# Input tensor x is assumed to be 3‑D: [batch, dim1, dim2].
# The kernel computes per output element (i.e., for each pair (b,i)) the
# arithmetic mean of the elements in group idx = b*dim1 + i over the last axis.
# ----------------------------------------------------------------------
mean_reduction_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void mean_reduction_kernel(const float* a, int num_groups, int dim_size, float* out) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_groups) {
        float sum = 0.0f;
        for (int j = 0; j < dim_size; ++j) {
            // a[idx * dim_size + j] corresponds to the elements of group idx along dimension 'dim_size'.
            sum += a[idx * dim_size + j];
        }
        out[idx] = sum / static_cast<float>(dim_size);
    }
}

torch::Tensor mean_reduction_cuda(torch::Tensor x) {
    auto size = x.numel();
    // Assume input is 3‑D: [batch, dim1, dim2]
    int batch = x.size(0)
    int dim1 = x.size(1)
    int dim2 = x.size(2)

    int num_groups = batch * dim1          // number of output elements after reducing dim2
    int dim_size   = dim2                  // size of the dimension to reduce over

    float* a_ptr = x.data_ptr<float()>
    float* out_ptr = torch::zeros_like(x)  // placeholder; we will overwrite only first num_groups entries later

    const int block_size = 256
    const int num_blocks = (num_groups + block_size - 1) / block_size

    mean_reduction_kernel<<<num_blocks, block_size>>>(a_ptr, num_groups, dim_size, out_ptr)

    return out_ptr
}
"""

# ----------------------------------------------------------------------
# Custom CUDA kernel for element‑wise addition.
# ----------------------------------------------------------------------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel()
    float* a_ptr = a.data_ptr<float()>
    float* b_ptr = b.data_ptr<float()>

    const int block_size = 256
    const int num_blocks = (size + block_size - 1) / block_size

    elementwise_add_kernel<<<num_blocks, block_size>>>(a_ptr, b_ptr, out_ptr, size)

    return torch::zeros_like(a)
}
"""

# ----------------------------------------------------------------------
# Register the custom operators with load_inline.
# ----------------------------------------------------------------------
elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

mean_reduction = load_inline(
    name="mean_reduction",
    cpp_sources=mean_reduction_kernel_source,
    cuda_sources=mean_reduction_kernel_source,
    functions=["mean_reduction_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.mean_reduction = mean_reduction

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.mean_reduction(x)
